class Lamp {
    int brightness_ = 0;          // invariant: 0–100
public:
    void setBrightness(int b) {
        if (b < 0) b = 0;
        if (b > 100) b = 100;
        brightness_ = b;
    }
    int brightness() const { return brightness_; }
};
